// ── EDIT ME ──────────────────────────────────────────────────
const CFG = {
  TEAMS_WEBHOOK_URL: 'REPLACE_TEAMS_WEBHOOK_URL',
  TARGET_TOUCHES_PER_DAY: 10,
  RECRUITERS: ['Recruiter 1', 'Recruiter 2', 'Recruiter 3', 'Recruiter 4'],
};
// ─────────────────────────────────────────────────────────────
const rows = $input.all().map((i) => i.json).filter((r) => r && r['Lead ID']);
const fmt = (ms) => new Date(ms).toISOString().slice(0, 10);
const today = fmt(Date.now());
const yesterday = fmt(Date.now() - 864e5);
const TOUCH_COLS = ['Touch 1 Sent', 'Touch 2 Sent', 'Touch 3 Sent', 'Touch 4 Sent'];

const signalsYesterday = rows.filter((r) => r['Signal Date'] === yesterday).length;

// Touches sent yesterday per recruiter (any touch column dated yesterday).
const touchLines = CFG.RECRUITERS.map((name) => {
  const mine = rows.filter((r) => r['Recruiter'] === name);
  let sent = 0;
  for (const r of mine) {
    for (const c of TOUCH_COLS) {
      if (String(r[c] ?? '').slice(0, 10) === yesterday) sent++;
    }
  }
  const flag = sent >= CFG.TARGET_TOUCHES_PER_DAY ? '✅' : '🔴';
  return '  ' + name + ': ' + sent + '/' + CFG.TARGET_TOUCHES_PER_DAY + ' ' + flag;
});

// Funnel snapshot by Status.
const statusCounts = {};
for (const r of rows) {
  const s = String(r['Status'] ?? 'New');
  statusCounts[s] = (statusCounts[s] ?? 0) + 1;
}
const funnel = Object.entries(statusCounts)
  .map(([s, n]) => s + ' ' + n)
  .join(' | ');

// SLA flags.
const untouched = rows.filter(
  (r) => String(r['Status']) === 'New' && String(r['Signal Date']) < today,
);
const awaitingReplyAction = rows.filter(
  (r) => String(r['Reply Date'] ?? '').trim() !== '' && ['New', 'Contacted', 'Accepted'].includes(String(r['Status'])),
);
const slaLines = [];
for (const r of untouched.slice(0, 5)) {
  slaLines.push('  ⏰ ' + (r['Company'] || r['Author']) + ' (' + r['Recruiter'] + ') — New since ' + r['Signal Date'] + ', no Touch 1');
}
for (const r of awaitingReplyAction.slice(0, 5)) {
  slaLines.push('  💬 ' + (r['Company'] || r['Author']) + ' (' + r['Recruiter'] + ') — replied ' + r['Reply Date'] + ', status still ' + r['Status']);
}
if (untouched.length > 5) slaLines.push('  …and ' + (untouched.length - 5) + ' more untouched New leads');

const text = [
  '📊 **STAFFING — CHANNEL A DAILY DIGEST** (' + today + ')',
  '',
  'Signals captured yesterday: **' + signalsYesterday + '**',
  '',
  '**Reach-outs yesterday** (target ' + CFG.TARGET_TOUCHES_PER_DAY + '/day):',
  ...touchLines,
  '',
  '**Funnel:** ' + (funnel || 'no leads yet'),
  '',
  slaLines.length ? '**Needs action:**' : '**Needs action:** none 🎉',
  ...slaLines,
].join('\n');

return [{ json: { text, webhook: CFG.TEAMS_WEBHOOK_URL } }];

// ── EDIT ME ──────────────────────────────────────────────────
const CFG = {
  UNIPILE_DSN: 'YOUR_UNIPILE_DSN',
  SEARCH_ACCOUNT_ID: 'YOUR_UNIPILE_ACCOUNT_ID',
  RESULTS_PER_QUERY: 20,
  QUERIES_PER_RUN: 4,
};
// ─────────────────────────────────────────────────────────────
const QUERIES = [
  '"we\'re hiring" developer',
  '"we are hiring" engineer',
  '"urgently hiring" "full stack"',
  '#hiring backend developer',
  '#hiring "data engineer"',
  '"we\'re hiring" devops',
  '"we are hiring" react developer',
  '"immediate joiner" python',
  '#hiring QA automation',
  '"we\'re hiring" azure',
  '"we are hiring" node.js',
  '"urgently hiring" frontend',
];
const sd = $getWorkflowStaticData('global');
const start = sd.queryCursor ?? 0;
const picked = [];
for (let i = 0; i < CFG.QUERIES_PER_RUN; i++) {
  picked.push(QUERIES[(start + i) % QUERIES.length]);
}
sd.queryCursor = (start + CFG.QUERIES_PER_RUN) % QUERIES.length;
return picked.map((q) => ({ json: { query: q, cfg: CFG } }));

// Flatten Unipile search responses into one post per item.
// NOTE: field names are written defensively — verify one raw
// response against the Unipile docs and tighten if needed.
const posts = [];
for (const item of $input.all()) {
  const body = item.json ?? {};
  const results = body.items ?? body.results ?? [];
  for (const r of results) {
    const p = r.post ?? r;
    const author = p.author ?? {};
    const id = p.id ?? p.social_id ?? p.share_url ?? null;
    const text = p.text ?? p.commentary ?? '';
    if (!id || !text) continue;
    posts.push({
      post_id: String(id),
      post_url: p.share_url ?? p.url ?? '',
      post_text: String(text),
      posted_at: p.parsed_datetime ?? p.date ?? '',
      author_name: author.name ?? [author.first_name, author.last_name].filter(Boolean).join(' ') ?? '',
      author_headline: author.headline ?? '',
      author_profile_url: author.profile_url ?? (author.public_identifier ? 'https://www.linkedin.com/in/' + author.public_identifier : ''),
    });
  }
}
return posts.map((p) => ({ json: p }));

// Dedupe new posts against the Leads sheet (source of truth) plus
// workflow static data as a fast path: same post never twice (14d),
// same author never twice within 30 days.
const posts = $('Normalize & Flatten Posts').all().map((i) => i.json);
const rows = $input.all().map((i) => i.json).filter((r) => r && !r.error);
const sheetIds = new Set(rows.map((r) => String(r['Lead ID'] ?? '')).filter(Boolean));
const sheetAuthors = new Set(rows.map((r) => String(r['Profile URL'] ?? '').toLowerCase()).filter(Boolean));
const sd = $getWorkflowStaticData('global');
sd.seenPosts = sd.seenPosts ?? {};
sd.seenAuthors = sd.seenAuthors ?? {};
const now = Date.now();
for (const [k, v] of Object.entries(sd.seenPosts)) { if (now - v > 14 * 864e5) delete sd.seenPosts[k]; }
for (const [k, v] of Object.entries(sd.seenAuthors)) { if (now - v > 30 * 864e5) delete sd.seenAuthors[k]; }
const fresh = [];
const runIds = new Set();
for (const p of posts) {
  const aKey = (p.author_profile_url || p.author_name || '').toLowerCase();
  if (runIds.has(p.post_id)) continue;
  if (sheetIds.has(p.post_id) || sd.seenPosts[p.post_id]) continue;
  if (aKey && (sheetAuthors.has(aKey) || sd.seenAuthors[aKey])) continue;
  runIds.add(p.post_id);
  sd.seenPosts[p.post_id] = now;
  if (aKey) sd.seenAuthors[aKey] = now;
  fresh.push(p);
}
return fresh.map((p) => ({ json: p }));

// Cheap regex gate before spending an LLM call.
const HIRE = /(hiring|open role|open position|join (our|the) team|looking for|immediate joiner|#hiring)/i;
const EXCLUDE = /(intern(ship)?|campus|fresher batch|walk-?in|#opentowork|open to work|i am looking for|seeking (a )?(new )?(role|opportunity))/i;
const out = [];
for (const item of $input.all()) {
  const t = item.json.post_text ?? '';
  if (t.length < 40) continue;
  if (!HIRE.test(t)) continue;
  if (EXCLUDE.test(t)) continue;
  out.push({ json: item.json });
}
return out;

const p = $json;
// Cheapest capable model — extraction/scoring is an easy task.
const MODEL = 'gemini-3.5-flash-lite';
// const MODEL = 'gemini-2.5-flash-lite';
const schema = {
  type: 'object',
  properties: {
    is_hiring_post: { type: 'boolean' },
    company: { type: ['string', 'null'] },
    roles: { type: 'array', items: { type: 'string' } },
    role_count: { type: 'integer' },
    location: { type: ['string', 'null'] },
    poster_title: { type: ['string', 'null'] },
    decision_maker: { type: 'boolean' },
    icp_score: { type: 'integer' },
    reasoning: { type: 'string' },
  },
  required: ['is_hiring_post', 'company', 'roles', 'role_count', 'location', 'poster_title', 'decision_maker', 'icp_score', 'reasoning'],
  additionalProperties: false,
};
const system = [
  "You are the lead-qualification engine for Techdome's staffing service line. You receive one LinkedIn post. Decide whether it is a genuine hiring post by an employer, extract the facts, and score ICP fit.",
  '',
  'Scoring (icp_score 0-100, start at 0):',
  '+40 hiring for tech roles Techdome can staff: software/web/mobile development, data engineering, DevOps/cloud, QA, AI/ML.',
  '+20 the poster is a decision-maker (founder, CxO, TA/HR lead, hiring manager, engineering manager) — judge from the headline.',
  '+15 multiple roles in one post (role_count >= 2); +5 more if role_count >= 5.',
  '+10 location is India, Southeast Asia, or the Middle East, or the post is remote-friendly.',
  '+15 the company appears to be a 50-2000-employee company or a funded startup that is scaling.',
  '',
  'Hard disqualifiers -> is_hiring_post=false and icp_score=0: job seekers or #OpenToWork posts, internship/campus/freshers-only hiring, staffing-agency spam or reposts, non-tech roles only, giant-enterprise procurement-style posts.',
  '',
  'reasoning: one short sentence. Respond with JSON only.',
].join('\n');
const user = 'AUTHOR: ' + (p.author_name || 'unknown') + '\nHEADLINE: ' + (p.author_headline || 'unknown') + '\nPOST URL: ' + (p.post_url || 'n/a') + '\nPOST TEXT:\n' + p.post_text;
return {
  json: {
    ...p,
    llm_model: MODEL,
    llm_request: {
      system_instruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: user }] }],
      generationConfig: {
        responseMimeType: 'application/json',
        responseJsonSchema: schema,
        maxOutputTokens: 2000,
        temperature: 0.2,
      },
    },
  },
};

const src = $('Build Gemini Extract Request').item.json;
const { llm_request, llm_model, ...lead } = src;
const resp = $json;
const empty = { is_hiring_post: false, company: null, roles: [], role_count: 0, location: null, poster_title: null, decision_maker: false, icp_score: 0, reasoning: '' };
const text = (resp.candidates?.[0]?.content?.parts ?? []).map((x) => x.text ?? '').join('');
let qual = null;
if (text && !resp.promptFeedback?.blockReason) {
  try { qual = JSON.parse(text); } catch (e) { qual = null; }
}
if (!qual) qual = { ...empty, reasoning: 'model_blocked_or_parse_error' };
return { json: { ...lead, qual } };

// ── EDIT ME ──────────────────────────────────────────────────
const CFG = {
  TEAMS_WEBHOOK_URL: '',   // optional — leave '' to skip Teams pings
  RECRUITERS: [
    { name: 'Recruiter 1', email: 'user@example.com' },
    { name: 'Recruiter 2', email: 'user@example.com' },
    { name: 'Recruiter 3', email: 'user@example.com' },
    { name: 'Recruiter 4', email: 'user@example.com' },
  ],
};
// ─────────────────────────────────────────────────────────────
// Round-robin, persisted across runs so assignment stays fair.
const sd = $getWorkflowStaticData('global');
let i = sd.rrIndex ?? 0;
const out = $input.all().map((item, idx) => {
  const recruiter = CFG.RECRUITERS[i % CFG.RECRUITERS.length];
  i++;
  return {
    json: { ...item.json, recruiter, cfg: CFG },
    pairedItem: item.pairedItem ?? { item: idx },
  };
});
sd.rrIndex = i % CFG.RECRUITERS.length;
return out;

const p = $json;
// Client-facing copy — worth the slightly bigger Flash model.
// Still free-tier / pennies. Drop to 'gemini-2.5-flash-lite' if quality holds.
const MODEL = 'gemini-3.5-flash';
const schema = {
  type: 'object',
  properties: {
    connection_request: { type: 'string' },
    first_message: { type: 'string' },
    value_nudge: { type: 'string' },
    final_touch: { type: 'string' },
  },
  required: ['connection_request', 'first_message', 'value_nudge', 'final_touch'],
  additionalProperties: false,
};
const system = [
  "You write LinkedIn outreach for Techdome's staffing team. The sender is " + p.recruiter.name + ', a recruiter at Techdome (yourcompany.com). Techdome places pre-vetted engineers with client teams, and every candidate submitted comes with a structured AI interview report from JustInterview.ai (tech screen, communication, scoring).',
  '',
  'Write 4 messages personalized to the specific post you are given:',
  '1. connection_request — max 270 characters, human, NO pitch. Mention the specific role/company from the post.',
  '2. first_message — sent after they accept: offer 2-3 interview-ready, AI-screened profiles within 48 hours for the specific role they posted. End with one clear question.',
  '3. value_nudge — follow-up if no reply (day 4): introduce the JustInterview.ai screening report as useful even if they fill the role internally; offer to send a sample report.',
  '4. final_touch — day 7: graceful close, door open for placements or AI screening later.',
  '',
  "Rules: plain text only (no markdown, no emojis), no buzzwords, never open with 'I hope this finds you well', reference something concrete from the post in messages 1 and 2, keep every message under 500 characters (connection_request under 270). Respond with JSON only.",
].join('\n');
const user = 'POST AUTHOR: ' + (p.author_name || 'unknown') + '\nAUTHOR HEADLINE: ' + (p.author_headline || 'unknown') + '\nEXTRACTED: ' + JSON.stringify(p.qual) + '\nPOST TEXT:\n' + p.post_text;
return {
  json: {
    ...p,
    llm_model: MODEL,
    llm_request: {
      system_instruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: user }] }],
      generationConfig: {
        responseMimeType: 'application/json',
        responseJsonSchema: schema,
        maxOutputTokens: 3000,
        temperature: 0.7,
      },
    },
  },
};

const src = $('Build Gemini Draft Request').item.json;
const { llm_request, llm_model, ...lead } = src;
const resp = $json;
const text = (resp.candidates?.[0]?.content?.parts ?? []).map((x) => x.text ?? '').join('');
let drafts = null;
if (text && !resp.promptFeedback?.blockReason) {
  try { drafts = JSON.parse(text); } catch (e) { drafts = null; }
}
if (!drafts || !drafts.connection_request) {
  // Fallback to the playbook skeleton so the recruiter always has something to send.
  const first = (lead.author_name || '').split(' ')[0] || 'there';
  const role = (lead.qual.roles || [])[0] || 'the role you posted';
  const company = lead.qual.company || 'your company';
  drafts = {
    connection_request: 'Hi ' + first + ' — saw you\'re hiring ' + role + ' at ' + company + '. We work with teams filling similar roles, thought it\'d be useful to connect.',
    first_message: 'Thanks for connecting! Quick one on the ' + role + ' opening — we run a bench of pre-vetted engineers and can usually put 2-3 interview-ready, AI-screened profiles in front of you within 48 hours. Worth a quick look for this role?',
    value_nudge: 'One thing that might be useful even if you fill this internally — every candidate we submit comes with a structured AI interview report (tech screen, communication, scoring) from our platform JustInterview.ai. Happy to send a sample report.',
    final_touch: 'Leaving this here, ' + first + ' — if the ' + role + ' search drags or screening volume becomes the bottleneck, we can help on either side (placements or AI screening). Good luck with the hire!',
  };
}
return { json: { ...lead, drafts } };
